import torch


def run(x, some, compute_uv):
    return torch.svd(x, some=some, compute_uv=compute_uv)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    x = inputs[0]
    compute_uv = bool(inputs[2]) if len(inputs) > 2 else True

    ref_u, ref_s, ref_v = ref_outputs[0], ref_outputs[1], ref_outputs[2]
    sol_u, sol_s, sol_v = sol_outputs[0], sol_outputs[1], sol_outputs[2]

    def to64(t):
        t = t.detach().to("cpu")
        return t.to(torch.complex128) if t.is_complex() else t.to(torch.float64)

    for a, b, name in ((sol_u, ref_u, "U"), (sol_s, ref_s, "S"), (sol_v, ref_v, "V")):
        if tuple(a.shape) != tuple(b.shape):
            return {"passed": False, "message": f"{name} shape {tuple(a.shape)} vs {tuple(b.shape)}", "metrics": {}}

    is_complex = x.is_complex()
    rs = to64(ref_s)
    ss = to64(sol_s)
    atol_s = 5e-4 if not compute_uv else (2e-2 if is_complex else 2e-3)
    if not torch.allclose(ss, rs, rtol=1e-3, atol=atol_s):
        diff = (ss - rs).abs().max().item()
        return {"passed": False, "message": f"S mismatch max_abs_diff={diff}", "metrics": {}}

    if compute_uv:
        u = to64(sol_u)
        s = to64(sol_s)
        v = to64(sol_v)
        k = s.shape[-1]
        recon = u[..., :, :k] @ torch.diag_embed(s).to(u.dtype) @ v[..., :, :k].mH
        xx = to64(x)
        atol_r = 2e-2 if is_complex else 2e-3
        if recon.numel() > 0 and not torch.allclose(recon, xx, rtol=1e-3, atol=atol_r):
            diff = (recon - xx).abs().max().item()
            return {"passed": False, "message": f"reconstruction mismatch max_abs_diff={diff}", "metrics": {}}
        for actual, name in ((u, "U"), (v, "V")):
            if actual.numel() == 0:
                continue
            kk = actual.shape[-1]
            eye = torch.eye(kk, dtype=actual.dtype, device=actual.device)
            gram = actual.mH @ actual
            eye = eye.expand_as(gram)
            if not torch.allclose(gram, eye, rtol=1e-3, atol=2e-2):
                diff = (gram - eye).abs().max().item()
                return {"passed": False, "message": f"{name} not orthonormal max_abs_diff={diff}", "metrics": {}}

    return {"passed": True, "message": "", "metrics": {}}
